begin;
select no_plan();
insert into auth.users(id,aud,role,email,email_confirmed_at)
values('60000000-0000-4000-8000-000000000001','authenticated','authenticated','gallery-one@example.test',now()),
('60000000-0000-4000-8000-000000000002','authenticated','authenticated','gallery-two@example.test',now()),
('60000000-0000-4000-8000-000000000003','authenticated','authenticated','gallery-unconfirmed@example.test',null);
select is(public.list_public_member_profiles()->>'total','0','existing accounts are not auto published');
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select is(public.get_my_directory_profile()->>'published','false','new member has private defaults');
select throws_ok($$select public.save_my_directory_profile('Builder','Bio',array['Robotics'],true,false,null)$$,'22023','Confirm public profile consent','explicit consent required');
select throws_ok($$select public.save_my_directory_profile('Builder','Bio',array['Robotics'],true,true,'2026-10-20-public-directory-v1',md5('synthetic/avatar-one.png'))$$,'22023','Upload a scanned profile avatar before sharing it','unscanned photo cannot be shared');
select lives_ok($$select public.save_my_directory_profile('Builder','Makes robots',array['Robotics','PCB'],true,false,'2026-10-20-public-directory-v1')$$,'confirmed Basic member can publish without ID approval');
select throws_ok($$select * from private.member_directory_profiles$$,'42501',null,'table inaccessible directly');
select throws_ok($$select public.read_public_directory_avatar(gen_random_uuid())$$,'42501',null,'storage paths inaccessible to members');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000002',true);
select is(public.get_my_directory_profile()->>'display_name','','another member cannot edit first profile');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.save_my_directory_profile('Unconfirmed','',array[]::text[],true,false,'2026-10-20-public-directory-v1')$$,'42501','Active Basic membership required','unconfirmed email cannot publish');
set local role anon;
select is(public.list_public_member_profiles('robotics')->>'total','1','anonymous search includes opted-in skills');
select is(public.list_public_member_profiles('no-match')->>'total','0','search filters results');
select is(public.list_public_member_profiles('',0,999)->>'page_size','48','public pagination is bounded');
select is((select array_agg(k order by k)::text from jsonb_object_keys(public.list_public_member_profiles()->'items'->0) k),'{bio,display_name,has_avatar,id,linkedin_url,public_email,skills}','public output excludes all private fields and auth IDs');
select throws_ok($$select public.get_my_directory_profile()$$,'42501',null,'anonymous cannot read private settings');
reset role;
insert into public.member_avatars(user_id,object_path,content_type,consent_version) values('60000000-0000-4000-8000-000000000001','synthetic/avatar-one.png','image/png','2026-09-27-avatar-1');
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select is(public.list_public_member_profiles()->'items'->0->>'has_avatar','false','old community consent does not expose photo');
select lives_ok($$select public.save_my_directory_profile('Builder','Makes robots',array['Robotics'],true,true,'2026-10-20-public-directory-v1',md5('synthetic/avatar-one.png'))$$,'explicit public photo consent allows retained avatar');
reset role;
select is(public.list_public_member_profiles()->'items'->0->>'has_avatar','true','consented avatar exposed');
select is(public.read_public_directory_avatar((public.list_public_member_profiles()->'items'->0->>'id')::uuid)->>'object_path','synthetic/avatar-one.png','service-only lookup is exact retained avatar');
update public.member_avatars set object_path='synthetic/avatar-two.png' where user_id='60000000-0000-4000-8000-000000000001';
select is(public.list_public_member_profiles()->'items'->0->>'has_avatar','false','replacement cannot inherit public photo consent');
set local role authenticated;
select throws_ok($$select public.save_my_directory_profile('Builder','Changed bio',array['Robotics'],true,true,'2026-10-20-public-directory-v1',md5('synthetic/avatar-one.png'))$$,'22023','Your profile photo changed. Reload and confirm public photo sharing again.','stale editor cannot publish replacement photo');
reset role;
select is(public.read_public_directory_avatar((public.list_public_member_profiles()->'items'->0->>'id')::uuid),null::jsonb,'replacement unavailable to public endpoint');
insert into public.memberships(user_id,status) values('60000000-0000-4000-8000-000000000001','suspended') on conflict(user_id) do update set status='suspended';
select is(public.list_public_member_profiles()->>'total','0','suspended account hidden immediately');
select is(public.get_public_member_profile((select id from private.member_directory_profiles where user_id='60000000-0000-4000-8000-000000000001')),null::jsonb,'direct profile lookup cannot bypass suspension');
update public.memberships set status='pending' where user_id='60000000-0000-4000-8000-000000000001';
update auth.users set banned_until=now()+interval '1 day' where id='60000000-0000-4000-8000-000000000001';
select is(public.list_public_member_profiles()->>'total','0','banned accounts hidden immediately');
update auth.users set banned_until=null where id='60000000-0000-4000-8000-000000000001';
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status)
values('60000000-0000-4000-8000-000000000001','Builder','gallery-one@example.test','+919000000001','https://linkedin.com/in/test','1990-01-01','revoked');
select is(public.list_public_member_profiles()->>'total','0','revoked membership hidden immediately');
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.save_my_directory_profile('Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1')$$,'42501','Active Basic membership required','revoked cannot republish');
select lives_ok($$select public.hide_my_directory_profile()$$,'revoked member can withdraw publication consent without validating edited fields');
reset role;
update public.basic_onboarding_applications set status='approved' where user_id='60000000-0000-4000-8000-000000000001';
select is(public.list_public_member_profiles()->>'total','0','unlisting persists after reinstatement');
select * from finish();
rollback;
